-- Jakarta place research checked on 2026-10-11. Sources are retained per field.
-- Membership is the primary offer, NOT proof that a brand forbids day passes.
-- Published coordinates are not on-site verification; GBK spots are community reports.
CREATE TABLE place_catalog (
  id varchar(255) PRIMARY KEY,
  name varchar(160) NOT NULL,
  mode training_mode NOT NULL,
  gym_category varchar(20),
  brand varchar(80),
  access_model varchar(30) NOT NULL,
  day_pass_available boolean,
  access_evidence varchar(20) NOT NULL,
  access_note text NOT NULL,
  area varchar(120) NOT NULL,
  city varchar(120) NOT NULL,
  address text NOT NULL,
  latitude numeric(10,7) NOT NULL,
  longitude numeric(10,7) NOT NULL,
  coordinate_scope varchar(20) NOT NULL,
  location_note text NOT NULL,
  google_maps_url text NOT NULL,
  equipment text[] NOT NULL DEFAULT '{}',
  sources jsonb NOT NULL,
  checked_at date NOT NULL,
  active boolean NOT NULL DEFAULT true,
  version bigint NOT NULL DEFAULT 1 CONSTRAINT place_catalog_version CHECK (version > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT place_catalog_category CHECK (
    (mode = 'gym' AND gym_category IS NOT NULL AND (
      (gym_category = 'brand' AND brand IS NOT NULL)
      OR (gym_category = 'conventional' AND brand IS NULL)))
    OR (mode = 'calisthenics' AND gym_category IS NULL AND brand IS NULL)
  ),
  CONSTRAINT place_catalog_access CHECK (
    access_model IN ('membership', 'per_visit', 'membership_or_per_visit', 'public', 'unknown')
    AND (access_model NOT IN ('per_visit', 'membership_or_per_visit') OR day_pass_available IS TRUE)
    AND (mode <> 'gym' OR access_model <> 'public')
  ),
  CONSTRAINT place_catalog_access_evidence CHECK (access_evidence IN ('operator', 'publisher', 'community', 'unknown')),
  CONSTRAINT place_catalog_coordinates CHECK (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180),
  CONSTRAINT place_catalog_coordinate_scope CHECK (coordinate_scope IN ('venue', 'workout_area')),
  CONSTRAINT place_catalog_sources CHECK (jsonb_typeof(sources) = 'array' AND jsonb_array_length(sources) > 0),
  CONSTRAINT place_catalog_maps_url CHECK (google_maps_url LIKE 'https://www.google.com/maps/%')
);
--> statement-breakpoint
CREATE INDEX place_catalog_filters_idx ON place_catalog (area, mode, gym_category, access_model);
--> statement-breakpoint
