INSERT INTO catalog_state (name, version) VALUES ('places', 1);
--> statement-breakpoint
CREATE FUNCTION update_place_catalog_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.version := OLD.version + 1;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER place_catalog_row_updated BEFORE UPDATE ON place_catalog
FOR EACH ROW EXECUTE FUNCTION update_place_catalog_row();
--> statement-breakpoint
CREATE FUNCTION bump_place_catalog_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE catalog_state SET version = version + 1 WHERE name = 'places';
  RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER place_catalog_version_changed AFTER INSERT OR UPDATE OR DELETE ON place_catalog
FOR EACH STATEMENT EXECUTE FUNCTION bump_place_catalog_version();

